from rest_framework.views import APIView
from rest_framework.response import Response
from rest_framework import permissions, status
from .models import StoredUserMessage

class PendingMessageAcknowledgmentView(APIView):
    permission_classes = [permissions.IsAuthenticated]

    def post(self, request, message_id):
        # Enforce that the message belongs to the requesting recipient
        try:
            msg = StoredUserMessage.objects.get(pk=message_id, recipient=request.user)
        except StoredUserMessage.DoesNotExist:
            return Response({'error': 'Message not found'}, status=status.HTTP_404_NOT_FOUND)

        msg.is_read = True
        msg.save(update_fields=['is_read'])
        return Response({
            'message_id': msg.id,
            'content': msg.message_text,
            'created_at': msg.created_at
        })
